// One paid checkout session -> everything the books and the email need.
const full = $('Get the full session').first().json;
const pi = full.payment_intent || {};
return [{ json: {
  invoiceNumber: (full.metadata || {}).invoice_number || '',
  invoiceId: (full.metadata || {}).invoice_id || '',
  amount: (full.amount_total || 0) / 100,
  charge: pi.latest_charge || '',
  email: (full.customer_details || {}).email || '',
  name: (full.customer_details || {}).name || '',
} }];
